mapper.select:
SELECT *, GROUP_CONCAT(DISTINCT t2.collectionId) AS collectionIds FROM( SELECT p.receipt_id_final AS receiptId, c.id AS contractId, co.id AS collectionId, p.client_id AS clientId, p.receipt_code AS receiptCode, c.contract_code AS contractCode, c.biz_type AS bizType, c.contract_status AS contractStatus, c.proj_sponsor_user_id AS projSponsorUserId, c.biz_dept_id AS bizDeptId FROM payment_base_info p INNER JOIN contract_base_info c ON p.contract_id = c.id INNER JOIN collection_base_info co ON co.cash_flow_item = 'RENT' AND co.contract_id = c.id AND co.receipt_id = p.receipt_id_final WHERE 1 = 1 AND p.client_id = #{dto.clientId} AND co.plan_collection_date >= #{dto.planCollectionDateFrom} AND co.plan_collection_date <= #{dto.planCollectionDateTo} AND c.biz_type = #{dto.bizType} AND c.contract_code LIKE CONCAT('%',#{dto.contractCode},'%')
AND c.id in
#{item}
AND c.contract_status = #{dto.contractStatus} AND c.biz_dept_id=#{dto.bizDeptId} AND c.proj_sponsor_user_id=#{dto.projSponsorUserId} AND co.write_off_status != 'WRITE_OFF_COMPLETED' AND co.write_off_status != 'WRITE_OFF_COMPLETED' AND co.plan_collection_date < SUBDATE(CURDATE(),3) AND co.write_off_status != 'WRITE_OFF_COMPLETED' AND co.email_notice_count = 0 AND co.plan_collection_date <= date_add(CURDATE(), INTERVAL 7 DAY) AND co.plan_collection_date >= CURDATE()
) t2 GROUP BY t2.receiptId
